fn a_lone_track_gap_and_an_invalid_resume_still_seal() {
    let mut pool = LiveCapturePool::new();
    let key = pool.start_record(0);
    assert!(pool.push(key, 0, 1, sample(1)));
    assert!(!pool.push(key, 0, 9, sample(9)));
